// The addon's shipped files. The compiled binary carries them (src/embedded-addon.ts, generated by
// scripts/build.ts) and writes them into ~/.wai/addon on install and update. A source checkout uses
// addon/ directly. Player data in the addon folder (Data.lua, ModuleDefs.lua, Generated.lua, ui/)
// is never shipped, so it's never touched.
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { ADDON_DIR, COMPILED } from "./files";

const MANIFEST = join(ADDON_DIR, ".manifest.json"); // { relative path: sha256 } of what we wrote

const sha256 = (bytes: Uint8Array) => new Bun.CryptoHasher("sha256").update(bytes).digest("hex");

// Returns whether any shipped file changed, which means WoW needs a restart to load it.
export async function extractAddon(): Promise<{ changed: boolean }> {
  if (!COMPILED) return { changed: false };
  const { files } = await import("./embedded-addon");
  const previous: Record<string, string> = await readFile(MANIFEST, "utf8").then(JSON.parse).catch(() => ({}));
  const next: Record<string, string> = {};
  let changed = false;
  for (const [rel, embedded] of files) {
    const bytes = new Uint8Array(await Bun.file(embedded).arrayBuffer());
    const hash = sha256(bytes);
    next[rel] = hash;
    if (previous[rel] === hash) continue;
    changed = true;
    await mkdir(dirname(join(ADDON_DIR, rel)), { recursive: true });
    await writeFile(join(ADDON_DIR, rel), bytes);
  }
  for (const rel of Object.keys(previous)) {
    if (rel in next) continue;
    changed = true;
    await rm(join(ADDON_DIR, rel), { force: true });
  }
  await mkdir(ADDON_DIR, { recursive: true });
  await writeFile(MANIFEST, JSON.stringify(next, null, 2));
  return { changed };
}
